      <div class="seg oa-atabs">${T.map(([k, t, n]) => `<button type="button" data-oaa="tab" data-v="${k}" class="${oa.adminTab === k ? 'active' : ''}">${esc(t)}${n ? ` <em>${n}</em>` : ''}</button>`).join('')}</div>
