    if (t === 'requests') return d.requests.length ? `<table class="gw-table"><thead><tr><th>Notice</th><th>Request</th><th>Status</th><th></th></tr></thead><tbody>${d.requests.map((r) => { const o = L.find((x) => x.id === r.auction_id) || {}; return `<tr><td>${esc(o.title || '')}<br><small>${esc(o.ref || '')}</small></td><td><b>${esc(r.kind)}</b> — ${esc(r.details)}<br><small>${esc(oaPKT(r.created_at))}</small></td><td>${esc(r.status)}${r.admin_note ? `<br><small>${esc(r.admin_note)}</small>` : ''}</td><td>${r.status === 'open' ? `<form class="v3x-form" data-oaa-req="${esc(r.id)}"><input name="note" maxlength="300" placeholder="What was done"><button class="button button-outline" type="submit" data-v="done">Done</button><button class="button button-ghost" type="submit" data-v="rejected">Decline</button></form>` : ''}</td></tr>`; }).join('')}</tbody></table><p class="form-hint">Apply the change with <b>Change status</b>, <b>Edit</b> or <b>Add corrigendum</b> on the notice, with the authority's source, then mark the request done.</p>` : '<div class="admin-empty">No change requests.</div>';
